INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-warring','韩','["韩","韩国"]',NULL,'cn','east_asia',-403,1,NULL,'year',-230,12,NULL,'month',-4824,-2737,'ochre',NULL,NULL,'三家分晋后韩氏立国，前403年周天子册命；前230年秦灭韩。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-fei','韩非','han-warring','[]',NULL,NULL,-280,1,NULL,'year',-233,1,NULL,'year','["思想家"]','法家集大成者，秦王政重其书，后遭李斯害死；代表作有《孤愤》《五蠹》，主张法、术、势并用；入秦后遭李斯构陷，在狱中自尽。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩非"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-jing','虔','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','前403年与魏、赵同受周室册封为诸侯，韩国正式立国，定都阳翟，开启战国历史，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩景侯"}]','景侯',NULL,'韩景侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r1','取','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','景侯之子，烈侯。在位十二年，韩国初立，实力一般，无力争霸，国势平稳，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩烈侯"}]','烈侯',NULL,'韩烈侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r10','安','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','韩国末代君主。前230年秦灭韩，国亡，韩国历史终结，姬姓韩国不复存在，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/安"}]',NULL,NULL,'安','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r2','猷','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','文侯，在位九年。韩国继续发展，未成大患，国势平稳，无力争霸，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩文侯"}]','文侯',NULL,'韩文侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r3','屯蒙','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','哀侯，在位仅三年。韩国实力尚弱，无力外争，维持小国局面，国势平平，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩哀侯"}]','哀侯',NULL,'韩哀侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r4','若山','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','共侯，曾与赵攻魏，于浊泽大胜。因与赵争利未灭魏，魏得以存续，韩国错失良机，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩共侯"}]','共侯',NULL,'韩共侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r5','武','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','即韩昭侯，任申不害变法，以术治国。韩国国力达于最强，诸侯不敢侵伐，为韩国巅峰，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩釐侯"}]','釐侯',NULL,'韩釐侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r6','康','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','昭侯之子，宣惠王。在位时韩国称王，参与合纵连横，国势尚可，无力争霸，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩宣惠王"}]','宣惠王',NULL,'韩宣惠王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r7','仓','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','襄王，在位十五年。与诸侯周旋，韩国已渐弱，无力争霸，国势转衰，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩襄王"}]','襄王',NULL,'韩襄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r8','咎','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位二十三年，秦国东进，韩国屡遭攻伐，割地求和，国势危急，濒临灭亡，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩釐王"}]','釐王',NULL,'韩釐王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r9','然','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','桓惠王，在位三十三年。韩国沦为秦国附庸，割地求和，国势危急，濒临灭亡，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩桓惠王"}]','桓惠王',NULL,'韩桓惠王','[]');
